package in.sevasetu.amc.security;
import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.List;
@Component public class JwtFilter extends OncePerRequestFilter{private final TokenService tokens;public JwtFilter(TokenService tokens){this.tokens=tokens;}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{var h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var u=tokens.verify(h.substring(7));var selected=r.getHeader("X-Tenant-Id");if(("ADMIN".equals(u.role())||"SALESPERSON".equals(u.role()))&&selected!=null&&!selected.isBlank())u=new CurrentUser(u.userId(),java.util.UUID.fromString(selected),null,u.username(),u.displayName(),u.role());SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u,null,List.of(new SimpleGrantedAuthority("ROLE_"+u.role()))));}catch(IllegalArgumentException ignored){}c.doFilter(r,s);}}
